  _ = `Details`,
  _ = `Beschrijving`,
  _ = `Zichtbaarheid`,
  _ = `Sectietitel`,
  _ = `Maak een keuze uit een lijst met al vertaalde standaardtitels om bovenaan deze sectie weer te geven of geef je eigen titel op. Begin met typen in het tekstveld om voorvertaalde titels te zoeken.`,
  _ = `Ondertitel`,
  _ = `(Max. %1$s tekens. Verschijnt bovenaan de pagina met evenements- of aankodigingsdetails.)`,
  _ = `(Max. aantal van %1$s tekens bereikt. Verschijnt bovenaan de pagina met evenements- of aankodigingsdetails.)`,
  _ = `Makersstartpagina's (v2) bieden een flexibele manier om je uitgevers-, ontwikkelaars- of franchise-pagina aan te passen.`,
  _ = `Deze pagina is niet zichtbaar. Publiceer de pagina eerst en daarna kun je hem instellen als je huidige makersstartpagina.`,
  _ = `Deze pagina <1>is niet</1> je huidige makersstartpagina. Ga naar het <2>dashboard van je makersstartpagina</2> om dit te activeren.`,
  _ = `Deze pagina is je huidige makersstartpagina. Je kunt dit beheren via het <1>dashboard van je makersstartpagina</1>.`,
  _ = `Avatar`,
  _ = `Bewerken: <1>editor voor makersstartpagina</1>`,
  _ = `Slogan`,
  _ = `Bewerken: <1>dashboard van je makersstartpagina</1>`,
  _ = `Welkom!`,
  _ = `<1>Jouw spellen</1> – Je spellen worden hieronder weergegeven in de lijst met gekoppelde apps en zijn klaar voor gebruik. Je kunt hieronder secties toevoegen en configureren om je spellen, DLC, demo's en soundtracks te promoten op de manier die geschikt is voor jouw producten.`,
  _ = `<1>Meer spellen koppelen</1> – Als er in de lijst hieronder spellen ontbreken, betekent dit dat je ze nog niet hebt gekoppeld aan deze makersstartpagina. Lees voor meer informatie over het koppelen van spellen aan je startpagina de documentatie <2>Ontwikkelaars- en uitgeversstartpagina's</2>.`,
  _ = `<1>Standaardconfiguratie</1> – Je vindt hieronder een aantal standaardsecties die al zijn geconfigureerd om je populaire, aanbevolen en recente uitgaven uit te lichten. Je kunt zoveel of zo weinig van deze secties gebruiken als je wilt.`,
  _ = `Raadpleeg de documentatie voor meer informatie`,
  _ = `Categorie: %1$s`,
  _ = `Fout bij dupliceren van evenement`,
  _ = `Er is een fout opgetreden bij het dupliceren: %1$s`,
  _ = `Fout bij publiceren van evenement`,
  _ = `Er is een fout opgetreden bij het publiceren van het evenement: %1$s`,
  _ = `Deze uitverkoop heeft een lange lijst van gekoppelde artikelen, dus de tags voor de artikelen worden overgenomen van de winkel. Dit kan even duren.`,
  _ = `Het is niet gelukt om de tags van de artikelen die meedoen aan deze uitverkoop over te nemen van de winkel, dus het is niet mogelijk om de editor veilig te openen. Laad de pagina opnieuw om het opnieuw te proberen.`,
  _ = `%1$s artikelen uit de lijst met gekoppelde artikelen kunnen niet vanuit de winkel worden geladen, waarschijnlijk omdat ze verbannen zijn of niet meer te koop worden aangeboden. De tags van deze artikelen zijn niet overgenomen, dus ze worden mogelijk niet weergegeven in secties op basis van tags (je kunt gewoon doorgaan als ze bijv. verbannen zijn): %2$s. `,
