  _ = `Wijzigingen aan het evenement opslaan ...`,
  _ = `Opslaan met succes voltooid.`,
  _ = `Wijzigingen zouden direct zichtbaar moeten zijn voor Steam-klanten.`,
  _ = `De volgende fouten in het huidige evenement verhinderen het opslaan van het eerder gepubliceerde evenement. Verbeter ze en probeer het opnieuw.`,
  _ = `Hieronder vind je waarschuwingen over het huidige evenement die je kunt negeren en die het opslaan niet verhinderen. We raden je echter aan om ze te corrigeren.`,
  _ = `Waarschuwingen overslaan en toch opslaan ...`,
  _ = `Het opslaan van het evenement is mislukt met de volgende fout:`,
  _ = `Dashboard`,
