  _ = `Openen`,
  _ = `Nieuw evenement of nieuwe aankondiging maken`,
  _ = `Concepten (verborgen, niet gepubliceerd)`,
  _ = `Dit is een lijst met opgeslagen evenementen die je nog steeds bewerkt. Ze zijn niet zichtbaar voor klanten en alleen leden van het communityteam van je spel kunnen ze zien. Wanneer ze klaar zijn, moet je deze evenementen publiceren voordat Steam-klanten ze kunnen zien.`,
  _ = `Geplande evenementen (verborgen, gepubliceerd)`,
  _ = `Dit is een lijst met ingeplande evenementen die op de opgegeven tijd automatisch zichtbaar worden. Je kunt deze evenementen blijven bewerken.`,
  _ = `Onvermelde evenementen (gepubliceerd, zichtbaar met een directe link)`,
  _ = `Deze evenementen zijn zichtbaar voor gebruikers met een directe link naar het evenement. Ze worden niet vermeld in lijsten en er worden geen automatische links aangemaakt vanuit het evenementsysteem.`,
  _ = `Openbaar zichtbare evenementen (zichtbaar, gepubliceerd)`,
  _ = `Dit is een lijst met evenementen die alle Steam-klanten op verscheidene plekken in de winkel, community en Steam-bibliotheek kunnen zien. Scroll naar beneden om er meer te laden.`,
  _ = `Uitgelicht`,
  _ = `Dit evenement is gemarkeerd als Uitgelicht. Het meest actuele uitgelichte evenement wordt voor spelers bovenaan de bibliotheekpagina van je spel weergegeven.`,
