  _ = `De taalinhoud voor %1$s is onvolledig. %2$s van de %3$s secties is/zijn ingevuld.`,
  _ = `Voor deze e-mail zijn merkillustraties in het Engels vereist. De e-mail kan zonder niet worden verzonden.`,
  _ = `Je moet ten minste een ontvangergroep voor de e-mail kiezen`,
