  _ = `Onder 'Ontvanger' dien je ten minste een selectievakje voor ontwikkelaars- of uitgeversrechten te kiezen.`,
  _ = `De opgegeven Youtube-URL kan niet worden geparseerd. Controleer de video-URL.`,
  _ = `E-mails kunnen niet opgesteld en uitgestuurd worden tot het onderliggende evenement gepubliceerd is en live staat. Gelieve het evenement eerst te publiceren.`,
  _ = `De e-mail heeft een vertaling naar het %1$s zonder merkillustraties in die taal. Daarom zal de Engelse merkillustratie worden getoond.`,
