  _ = `De e-mail is klaar om verzonden te worden. Wil je de e-mail vergrendelen om verdere wijzigingen te voorkomen? Dit zal de e-mail niet versturen, maar deze alleen gereed maken voor verzending.`,
  _ = `De volgende waarschuwing is opgetreden. Je kunt de fout corrigeren voordat je de e-mailinhoud vastlegt.`,
  _ = `We zijn tijdens het voorbereiden de volgende fouten tegengekomen die verhinderen dat de e-mail wordt verstuurd:`,
  _ = `Even geduld terwijl de e-mail wordt voorbereid`,
