  _ = `Wijzigingen opslaan`,
  _ = `Titel verwijderen`,
  _ = `Dit verwijdert de aangepaste titel voor deze taal. Aangepaste titels moeten eerst worden verwijderd als je de oorspronkelijke, onvertaalde naam wilt gebruiken.`,
  _ = `Aan whitelist toevoegen`,
