  _ = `Whitelist wissen`,
  _ = `Vind je vriendcode op deze pagina: %1$s`,
  _ = `Uitzendingschat`,
  _ = `Bepaalt of de chatinterface wel of niet naast de uitzending wordt getoond`,
  _ = `Chat standaard tonen`,
  _ = `Chat standaard verbergen`,
  _ = `Chat van product- en evenementenpagina verwijderen`,
  _ = `Voorwerpdrops`,
  _ = `Voorwerpdrops voor deze uitzending inschakelen?`,
  _ = `Worden de drops handmatig uitgevoerd?`,
  _ = `Hoe lang (in minuten) duurt het voordat ik in aanmerking kom voor een drop?`,
  _ = `(Optioneel) Maak een Steam-evenement met een meer uitgebreide beschrijving voor de drops. Dit is handig bij uitverkopen waar de hoofdtekst van het evenement niet zichtbaar is.`,
  _ = `Clan-account-ID`,
  _ = `Clan-evenement-GID`,
  _ = `Meerdere spelers weergeven`,
  _ = `Wanneer dit is ingesteld, worden de linker- en rechterkolommen naast het venster met de speler weggehaald. Dit is enkel nuttig wanneer er voor het evenement slechts één stream wordt uitgezonden en kolommen enkel de aandacht zouden afleiden.`,
  _ = `Modus met meerdere spelers inschakelen`,
  _ = `Wanneer dit wordt toegestaan, wordt er een knop weergegeven waarmee de chat kan worden weergegeven of verborgen. Als de chat wordt weergegeven, schakelt de weergave terug naar de standaard modus. Als de chat wordt verborgen, schakelt de weergave weer over naar de modus met meerdere spelers.`,
  _ = `Chat weergeven/verbergen toestaan`,
  _ = `Aankondigingen van winnaars weergeven`,
  _ = `Weggeefactie-ID invoeren`,
  _ = `Als er voor de weggeefactie een uitzending wordt georganiseerd waarbij de winnaars via de chat worden bekendgemaakt, dan kun je met behulp van een weggeefactie-ID toestaan dat chatberichten ook na het sluiten van de chat beschikbaar blijven, zodat de aankondigingen later kunnen worden bekeken.`,
  _ = `Uitzendingstitel`,
  _ = `Maak een keuze uit een lijst met standaardtitels om boven je uitzending op je winkelpagina te tonen of voer een aangepaste titel in.`,
  _ = `Titel invoeren`,
  _ = `Documentatie weergeven`,
  _ = `Beeldmateriaal voor uitzending`,
  _ = `Illustraties voor uitzending: opties`,
  _ = `Rechter- en linkerbanners tonen in plaats van de spelcapsule.`,
  _ = `Als dit is ingeschakeld, verschijnt de banner in de Steam-winkel in plaats van in de spelcapsules. Dit kan handig zijn als de banner meer informatie bevat over het evenement dan de specifieke appcapsule(s), of als je meerdere spellen gespreid over de tijd wilt streamen maar slechts één enkel evenementgerelateerd element wilt tonen.`,
  _ = `Whitelist van uitzenders`,
  _ = `Ongeldig SteamID opgegeven. Het moet een een numerieke waarde van 64 bits zijn.`,
  _ = `Uitzendingsachtergrond`,
  _ = `Achtergrondverloop (binnenste kleur)`,
  _ = `Achtergrondverloop (buitenste kleur)`,
  _ = `Gebruikersinformatie laden mislukt`,
  _ = `Optionele instelling die het mogelijk maakt om voor je publiek aan te geven dat een uitzending in een bepaalde taal is. Dit kan handig zijn als er bijvoorbeeld uitzendingen zijn in verschillende talen voor een evenement, en laat ons toe de beste standaardstream te kiezen voor een gebruiker gebaseerd op hun taal.`,
  _ = `Prioriteit`,
  _ = `Welke prioriteit deze uitzending ten opzichte van andere uitzendingen heeft. Uitzendingen met de hoogste prioriteit krijgen voorrang. Als meerdere uitzendingen dezelfde prioriteit hebben, wordt er willekeurig een als standaard gekozen.`,
  _ = `Primair (hoogst)`,
  _ = `Uitgelicht (hoog)`,
  _ = `Standaard (gemiddeld)`,
  _ = `Algemeen (laag)`,
  _ = `Type gestreamde inhoud`,
  _ = `Dit beschrijft of de inhoud live wordt gestreamd, of eerder opgenomen is. In het laatste geval geeft dit ook aan of de inhoud voor het eerst op het platform wordt uitgezonden, of het een herhaling is.`,
  _ = `Onbekend / Niet opgegeven`,
