  _ = `Je kunt maar één sectie met tabbladen gebruiken binnen een uitverkoop`,
  _ = `Kies een titel voor het tabblad`,
  _ = `Maak een keuze uit een lijst met al vertaalde standaardtitels voor dit tabblad, of kies een aangepaste titel en voer je eigen naam voor elke taal in`,
  _ = `Filteren op secties die zichtbaar zijn op dit tabblad`,
  _ = `Tijdelijk alleen de secties in de editor laten zien die zichtbaar zijn op dit tabblad. Dit is alleen van toepassing tijdens het bewerken.`,
  _ = `Tabblad verbergen`,
  _ = `Zichtbaarheid tabbladen`,
  _ = `Instellingen om te bepalen of gebruikers het tabblad op hun uitverkooppagina te zien krijgen.`,
  _ = `Zichtbaarheidsinstellingen per land inschakelen?`,
  _ = `Lijst met toegestane landen`,
  _ = `Dit is een lijst met tweeletterige landcodes, door komma's gescheiden. Deze wordt alleen weergegeven in toegestane landen.`,
  _ = `Lijst met niet-toegestane landen`,
  _ = `Dit is een lijst met tweeletterige landcodes, door komma's gescheiden. Deze wordt niet weergegeven in niet-toegestane landen.`,
  _ = `Zichtbaarheidsinstellingen per pakket inschakelen?`,
  _ = `Lijst met toegestane pakketten`,
  _ = `Dit is een lijst met pakket-ID's, door komma's gescheiden. Dit tabblad wordt alleen weergegeven als de gebruiker een van de pakketten in de lijst heeft.`,
  _ = `Zichtbaarheidsinstellingen van hardwaregebruik inschakelen?`,
  _ = `Dit tabblad wordt alleen weergegeven als de gebruiker een van deze hardwareapparaten heeft gebruikt. Als een van deze opties aangevinkt is, wordt de sectie niet weergegeven voor gebruikers die zijn uitgelogd.`,
  _ = `Lijst met toegestane hardware`,
  _ = `Huidige tabbladen`,
  _ = `Elk tabblad definieert een getitelde verzameling artikelen, waarmee de volgende secties kunnen worden gefilterd om enkel die artikelen te tonen.`,
  _ = `Tabbladen zijn een soort filter waarmee wordt bepaald welke secties worden weergegeven. Stel hier tabbladen in en ga dan naar de secties om te selecteren op welke tabbladen ze moet worden weergegeven. Secties zijn standaard zichtbaar op alle tabbladen.`,
  _ = `Selecteer hier een tabblad om alleen de secties in de editor te laten zien die zichtbaar zijn op dit tabblad. Dit is alleen van toepassing tijdens het bewerken.`,
  _ = `%1$s tabblad`,
  _ = `%1$s tabbladen`,
