  _ = `Kleuren voor geselecteerde/gemarkeerde tabbladen`,
  _ = `Hiermee kun je de standaardkleuren voor geselecteerde en gemarkeerde tabbladen wijzigen. Verwijder de instelling om de standaardkleuren weer te gebruiken.`,
  _ = `Gefilterde itemlijst van tab`,
  _ = `De volgende items worden als filter gebruikt. Als dit tabblad geselecteerd is, kunnen in de secties die erop volgen enkel items die op deze lijst staan weergegeven worden`,
  _ = `%1$s – Artikelen: %2$s`,
  _ = `%1$s – Alle items tonen`,
  _ = `Dit tabblad is ingesteld om alle artikelen te tonen in de secties die volgen. Als je hieronder klikt, kun je echter een lijst met artikelen maken die ervoor zorgt dat, als dit tabblad actief is, enkel de items die in deze lijst voorkomen weergegeven zullen worden in de secties die volgen.`,
  _ = `Gefilterde items bewerken`,
  _ = `Individuele achtergrondafbeelding voor tabbladen (optioneel)`,
  _ = `Hiermee kun je voor elk afzonderlijk tabblad een aparte achtergrondafbeelding instellen die getoond wordt als het tabblad is geselecteerd. De afbeelding neemt de hele lengte van de tabbladnavigatiebalk in, bovenaan het scherm.`,
  _ = `Let op: Bij het gebruik van filters wordt het dialoogvenster 'Compatibiliteit met Steam Deck tonen' automatisch toegevoegd aan capsules en weergegeven bij het aanwijzen met de muis.`,
  _ = `Let op: Bij het gebruik van filters wordt het dialoogvenster 'Compatibiliteit met Steam Frame tonen' automatisch toegevoegd aan capsules en weergegeven bij het aanwijzen met de muis.`,
