  _ = `De agenda haalt automatisch evenementen op van uitgelichte spellen die op de verkooppagina getoond worden, en geeft deze gesorteerd weer op de starttijd voor het evenement. Dit is handig om uitzendingen weer te geven die tijdens de uitverkoop zullen plaatsvinden.`,
