  _ = `Hiermee kun je producten zoeken op naam, of links naar apps, pakketten of bundels plakken om toe te voegen aan de lijst.`,
  _ = `Selecteer evenementen om uit te lichten`,
  _ = `Voer evenement-ID in om te selecteren`,
  _ = `Voer evenement-URL in om te selecteren`,
  _ = `Voer de volledige evenement-URL in en selecteer dan vanuit het menu voor automatisch aanvullen. Het evenement moet openbaar zichtbaar zijn om toegevoegd te kunnen worden.`,
  _ = `Evenement is niet geldig.`,
  _ = `De evenement-ID is de laatste reeks cijfers in het staartje van de URL voor je evenement`,
  _ = `De begin- en eindtijd van het evenement moeten binnen het tijdvak van de agendawidget vallen. Het evenement moet ook van het verwachte type zijn, als dit is opgegeven.`,
  _ = `Selecteer een tag om uit te lichten`,
  _ = `Selecteer een categorie om uit te lichten`,
  _ = `Slimme sectie: tags voor evenementen waarmee je evenementen kunt filteren voor alle spellen`,
  _ = `Voer tagnaam in zonder spaties`,
  _ = `Als dit is ingesteld, worden alle spellen in de carrousel opgenomen, zelfs spellen die niet expliciet inbegrepen zijn bij deze uitverkoop. We geven de voorkeur aan evenementen van spellen waarin de gebruiker interesse toont (in bezit, op verlanglijst, gevolgd), met bestverkochte spellen als plaatsvervangers indien er niet genoeg zijn.`,
  _ = `Max. aantal te laden evenementen`,
  _ = `Het maximale aantal evenementen dat van de server moet worden gedownload. We raden aan om minimaal 15 in te vullen. Het maximale aantal is 100.`,
  _ = `Standaard aantal weer te geven evenementen: %1$s`,
  _ = `Datums/tijden van evenementen`,
  _ = `Als dit niet ingesteld is, gebruiken we de start- en einddatum van het uitverkoopevenement. Het is echter mogelijk dat evenementen mogen lopen voor een langere tijdspanne dan het uitverkoopevenement. Vul in dat geval deze velden in.`,
  _ = `Volgorde omkeren (meest recente evenement eerst)`,
  _ = `Als dit is aangevinkt, worden evenementen met de meest recente begindata eerst weergegeven.`,
  _ = `Knop 'Alle evenementen weergeven' verbergen`,
  _ = `(Alleen van toepassing op de inhoudshub van de verkooppagina.) Verbergt de knop 'Alle evenementen weergeven' die rechtsboven in de evenementencarrousel wordt weergegeven.`,
  _ = `Bron voor recente getagde evenementen:`,
  _ = `Alles`,
  _ = `Evenementen weergeven van alle spellen in de Steam-winkel (niet beperkt tot de uitverkooppagina of inhoudshub, maar tabblad en sectie worden wel gefilterd).`,
  _ = `Verlanglijst`,
