  _ = `URL van de link`,
  _ = `Optioneel veld. Wanneer ingesteld, staat het gebruikers toe om door op de titel van deze sectie te klikken naar een bepaalde locatie in de winkel te gaan.`,
  _ = `URL van de link voor Steam China`,
  _ = `Alleen locaties op store.steampowered.com of steamcommunity.com zijn toegestaan. Als er een URL wordt toegevoegd, wordt de gebruiker na het klikken op deze afbeelding doorgeleid naar een andere locatie in de winkel of community.`,
