  _ = `Alleen media (geen tekst)`,
  _ = `Media links horizontaal uitlijnen`,
  _ = `Media gecentreerd horizontaal uitlijnen`,
  _ = `Media rechts horizontaal uitlijnen`,
  _ = `Media bovenaan verticaal uitlijnen`,
  _ = `Media gecentreerd verticaal uitlijnen`,
  _ = `Media onderaan verticaal uitlijnen`,
  _ = `Marges vergroten vanaf het begin van het vak`,
  _ = `Marges aan beide kanten evenveel vergroten`,
  _ = `Marges vergroten vanaf het eind van het vak`,
  _ = `Screenshot weergeven`,
  _ = `Microtrailer weergeven`,
  _ = `Screenshot weergeven, microtrailer bij aanwijzen`,
  _ = `Afspeelknop trailer`,
  _ = `Kleur afspeelknop`,
  _ = `Kleur van de afspeelknop die voor elke trailer in deze sectie wordt weergegeven. Laat deze optie leeg om de standaardkleur te gebruiken.`,
  _ = `Kleur afspeelknop bij aanwijzen`,
  _ = `Kleur van de afspeelknop wanneer de lezer de trailer aanwijst. Deze kleur wordt toegepast op elke trailer in deze sectie. Laat deze optie leeg om de standaardkleur te gebruiken.`,
  _ = `Standaard trailerweergave`,
  _ = `Bepaalt hoe de media eruitziet voordat erop wordt geklikt: de screenshot van de trailer, de microtrailer die zich herhaalt of de screenshot die bij het aanwijzen verandert in een microtrailer die zich herhaalt. Door op een van deze opties te klikken, wordt de trailer in een dialoogvenster afgespeeld.`,
  _ = `Beeldverhouding`,
  _ = `16:9`,
  _ = `Breedte-hoogte-verhouding van het beeldmateriaal, zodat de pagina deze ruimte kan vrijhouden tijdens het laden. Deze informatie wordt opgeslagen bij het uploaden van het beeldmateriaal. Voer de gegevens handmatig in voor beeldmateriaal dat eerder is geüpload.`,
  _ = `Grootte opzoeken`,
  _ = `Geconverteerd naar %1$s x %2$s (%3$s)`,
  _ = `Gebruiken`,
  _ = `Grootte van dit bestand niet opgeslagen.`,
  _ = `Alternatieve tekst`,
  _ = `Tekst voor schermlezers of voor wanneer de afbeelding niet kan worden geladen.`,
  _ = `Optionele URL`,
  _ = `Voer hier optioneel een URL in`,
  _ = `Je kunt hier optioneel een URL opgeven die geopend moet worden als de gebruiker op de media klikt.`,
  _ = `Rijen rangschikken`,
  _ = `Hiermee kunnen de rijen in het raster opnieuw worden gerangschikt.`,
  _ = `Pagina's rangschikken`,
  _ = `Hiermee kunnen carrouselpagina's opnieuw worden gerangschikt.`,
  _ = `Grote kop`,
  _ = `Middelgrote kop`,
  _ = `Kleine kop`,
