  _ = `Optionele beschrijving`,
  _ = `Optionele titel`,
  _ = `Optionele ondertitel`,
  _ = `Media`,
  _ = `Titelindeling`,
  _ = `Tekst gebruiken voor titel en ondertitel`,
  _ = `Afbeelding of video`,
  _ = `Speltrailer`,
  _ = `Met deze optie kun je een openbare trailer selecteren in plaats van geüploade media.`,
  _ = `H1`,
  _ = `H2`,
  _ = `H3`,
  _ = `Media-overlay`,
  _ = `Bevat een media-element (video of afbeelding) met een overlay van tekst.`,
  _ = `Locatie tekstoverlay`,
  _ = `linksboven`,
  _ = `middenboven`,
  _ = `rechtsboven`,
  _ = `linksmidden`,
  _ = `midden`,
  _ = `rechtsmidden`,
  _ = `linksonder`,
