  _ = `Onbekend sectietype`,
  _ = `Deze sectie bevat alleen een afbeelding. Wil je de sectie <1>converteren</1> naar een titelafbeeldingssectie?`,
  _ = `Afbeeldingssecties maken het makkelijker om de afbeelding te lokaliseren en worden sneller gerenderd op de uiteindelijke uitverkooppagina voor klanten. Afbeeldingen die in de titelkop worden gebruikt, worden ook niet opgenomen in de selectietool voor afbeeldingen, zodat die overzichtelijker blijft.`,
  _ = `Voorbeeld van gedeelde inhoud op sociale media`,
