  _ = `(Beschrijving wordt overgenomen van de beschrijving van de makersstartpagina)`,
  _ = `Standaardafbeelding voor de pagina op sociale media (gebaseerd op de hoofdafbeelding): `,
  _ = `Gebruik de uitverkoopsectie van de editor voor delen op sociale media om inhoud aan te passen`,
  _ = `'Delen met vrienden' weergeven (standaard ingeschakeld)`,
  _ = `De standaardinhoud voor sociale media is overschreven door de uitverkoopsectie van de editor voor delen op sociale media`,
