  _ = `Achtergrond en illustraties voor uitverkooppagina`,
  _ = `Pagina-achtergrond`,
  _ = `Alles verwijderen`,
  _ = `Verwijdert alle items van de bovenstaande lijst`,
  _ = `Met onbewerkte gegevens werken`,
  _ = `Hiermee kun je de lijst met gelinkte artikelen voor deze uitverkoop rechtstreeks bewerken. Dit kun je gebruiken om te importeren uit of exporteren naar programma's zoals Excel, of om snel grote veranderingen te maken aan de lijst artikelen.`,
  _ = `Aangepaste labels`,
  _ = `Dit maakt het mogelijk om de lijst met gelinkte artikelen in deze uitverkoop rechtstreeks te bewerken en enkel de aangepaste verzameling van labels voor de uitverkoopartikelen te importeren of exporteren. Dit wordt voornamelijk gebruikt om een selectie aangepaste labels te importeren die beheerd wordt door een externe spreadsheet, zonder de andere labels van de artikelen te wijzigen. Omdat dit artikelen die niet in de lijst staan niet zal verwijderen, kun je er ook een deel van importeren via dit dialoogvenster.`,
  _ = `Importeren vanuit de aanmeldingspagina`,
  _ = `Opent een dialoogvenster waarmee je alle apps kunt importeren vanaf een aanmeldingspagina en deze toevoegen aan de lijst met gelinkte artikelen.`,
  _ = `Artikelen synchroniseren`,
  _ = `Demolabels synchroniseren`,
  _ = `Deze actie overloopt alle gelinkte artikelen en voegt het label 'heeftdemo' (HasDemo) toe aan alle apps die een demo hebben, en verwijdert dit label van alle apps die geen demo hebben.`,
  _ = `Synchroniseren`,
  _ = `Dit zorgt ervoor dat verschillende labels en andere informatie tussen de gelinkte artikelen en andere bronnen kunnen worden gesynchroniseerd.`,
  _ = `Demolabels synchroniseren ...`,
  _ = `Automatische labels bewerken`,
  _ = `Labelnaam invoeren`,
  _ = `Deze tekst vormt de titel van het label en wordt toegevoegd aan alle gelinkte artikelen die overeenkomen met het gekoppelde filter.`,
  _ = `Itemfilters wijzigen (%1$s filters)`,
  _ = `Itemfilters wijzigen (%1$s filters) (%2$s eruit gefilterd)`,
  _ = `Hiermee kun je een filter instellen dat op alle gelinkte artikelen zal worden toegepast voordat ze aan secties worden toegevoegd. Hiermee kun je bijvoorbeeld alle spellen zonder demo eruit filteren, of spellen met een label dat jij bepaalt.`,
  _ = `Verkennen`,
  _ = `Hiermee kun je de filtertool gebruiken om de momenteel ingestelde gelinkte artikelen te bekijken. Je kunt zien hoeveel artikelen er met verschillende filters overblijven, of welke labels er aan artikelen zijn gekoppeld.`,
  _ = `Bundels bewerken`,
  _ = `Hiermee kun je gelinkte artikelen als bundels bewerken. Je kunt een lijst artikelen invoeren en er gemeenschappelijke labels aan toevoegen of van verwijderen`,
  _ = `Automatische labels`,
  _ = `Dit maakt het gebruik van automatische labels mogelijk. Automatische labels zijn filters die een bepaalde labelnaam toevoegen aan alle artikelen die met het filter overeenkomen.`,
  _ = `Itemweergave`,
  _ = `Items tonen (behalve eruit gefilterde items)`,
  _ = `Alle items tonen`,
  _ = `Eruit gefilterde items tonen`,
  _ = `Aanmeldingspagina importeren`,
  _ = `Aanmeldingsnaam`,
  _ = `Dit is de naam van de uitverkoop waar op de aanmeldingspagina naar wordt verwezen, zodat duidelijk is uit welke uitverkoop gegevens moeten worden geïmporteerd.`,
  _ = `Voorvoegsel label`,
  _ = `Een voorvoegsel voor labels, aangeleverd door de aanmeldingspagina. Dit maakt het mogelijk om de actie getoond op de aanmeldingspagina anders te maken dan de actie op de winkelpagina.`,
  _ = `Demo's verplichten`,
  _ = `Als dit is aangevinkt, worden enkel apps getoond die een demo hebben`,
  _ = `Apps laden vanaf de inschrijfpagina...`,
  _ = `Winkeldefinities laden om apps zonder winkelpagina eruit te kunnen filteren`,
  _ = `We laden winkeltags voor %1$s apps ...`,
  _ = `We laden eigenschappen voor %1$s apps ...`,
  _ = `Demo-informatie laden voor %1$s apps...`,
  _ = `Winkeltags laden voor %1$s apps...`,
  _ = `Hiermee kun je de lijst van elementen voor deze capsule op een geavanceerde manier bewerken in een tekstindeling die groepsimporteren of exporteren vanaf externe tools mogelijk maakt.`,
  _ = `Sectie-items bewerken`,
  _ = `Specificeer de elementen en de rangorde waarin je ze wilt weergeven.`,
  _ = `Elk element start met de ID, gevolgd door een type (optioneel) en een dag (optioneel).`,
