  _ = `Hoofdapps sorteren op`,
  _ = `Speeltijd`,
  _ = `Hiermee worden hoofdapps gesorteerd op totale speeltijd, met de meest gespeelde bovenaan.`,
  _ = `Laatst gespeeld`,
  _ = `Hiermee worden hoofdapps gesorteerd op het tijdstip waarop het spel voor het laatst is gespeeld, met de meest recent gespeelde bovenaan.`,
  _ = `Populair`,
  _ = `Hiermee worden hoofdapps gesorteerd op populariteit, met de meeste populaire DLC's bovenaan. Populariteit wordt bepaald op basis van verkooprang, dus DLC's die weinig worden verkocht worden mogelijk niet weergegeven.`,
  _ = `Maximale tijd laatst gespeeld (maanden)`,
