  _ = `Hoofdapps om weer te geven`,
  _ = `Bij het laden van de pagina wordt alleen DLC weergegeven voor maximaal dit aantal spellen. Als er DLC voor meer spellen beschikbaar zijn, verschijnt de knop 'Meer tonen'.`,
  _ = `DLC-statistieken verbergen`,
