  _ = `Sorry, we kunnen die pagina niet vinden.`,
  _ = `Naar het dashboard`,
  _ = `Selecteer een of meerdere bestanden om gelokaliseerde tekst te importeren voor je titel en hoofdtekst. We lezen aan de hand van de bestandsextensie of je een XML- of een CSV-bestand importeert. Voor XML-bestanden gebruiken we de API-taalcode aan het einde van de bestandsnaam net voor de extensie om te bepalen in welke taal de inhoud is opgesteld. Exporteer eerst een CSV- of XML-bestand, zodat je kunt controleren of je de correcte bestandsindeling gebruikt.`,
  _ = `Dit exporteert de huidige taal naar een enkel bestand van het geselecteerde type. XML maakt altijd een enkel bestand aan met de huidige taal van de editor. Met CSV worden alle beschikbare talen naar één bestand geëxporteerd.`,
