  _ = `Als je deze sectie voor veelgestelde vragen verwijdert, gebeurt dit onmiddellijk en dit kan niet ongedaan worden gemaakt. Weet je zeker dat je dit artikel en alle eraan gekoppelde vertalingen wilt verwijderen?`,
  _ = `De veelgestelde vragen-sectie wordt verwijderd. Even geduld`,
