  _ = `Zichtbaarheid wijzigen`,
  _ = `Bewerken`,
  _ = `Selecteer hier opties om deze veelgestelde vragen zichtbaar te maken in het gewenste domein. Om ze zichtbaar te maken, moet er ook een gepubliceerde versie zijn in de gevraagde taal, of een terugvaloptie geschikt voor het domein.`,
  _ = `De zichtbaarheid van de veelgestelde vragen voor een bepaald domein kun je via dit dialoogvenster wijzigen. Als het document niet zichtbaar is dan zal het niet beschikbaar zijn, ook al is het gepubliceerd.`,
